/*-
 * SPDX-License-Identifier: BSD-2-Clause
 *
 * sys.rs — the C declarations the front-end uses, generated by bindgen from
 * sys.h at build time (RUST_BINDGEN_* in ../gpu/Makefile): the backend's BO
 * and VM structs, the backend vtable, the ioctl ABI structs and numbers, and
 * the glue functions. The softc is opaque.
 */
#![allow(warnings, nonstandard_style, dead_code, unsafe_op_in_unsafe_fn)]

include!(concat!(env!("OUT_DIR"), "/modsys.rs"));

/// The device softc, C's alone: Rust holds pointers to it and reaches its fields only through
/// the glue functions (amd_rs_*).
#[repr(C)]
pub struct atrium_amd_softc {
    _private: [u8; 0],
}
